  await dataSource.query(
    'TRUNCATE TABLE "deal_contact_links", "contact_company_links", "deals", "contacts", "companies" RESTART IDENTITY CASCADE',
  );
};

export const cleanupCompaniesByPrefixes = async (
  { dataSource }: SeedContext,
  prefixes: string[],
) => {
  if (prefixes.length === 0) {
    return;
  }

  const companyRepository = dataSource.getRepository(CompanyEntity);
  const companies = await companyRepository
    .createQueryBuilder('company')
    .select('company.id', 'id')
    .where(
      prefixes
        .map((_, index) => `company.name LIKE :prefix${index}`)
        .join(' OR '),
      Object.fromEntries(
        prefixes.map((prefix, index) => [`prefix${index}`, `${prefix}%`]),
      ),
    )
    .getRawMany<{ id: string }>();

  if (companies.length === 0) {
    return;
  }

  const companyIds = companies.map(({ id }) => id);

  const dealRepository = dataSource.getRepository(DealEntity);
  const dealContactLinkRepository = dataSource.getRepository(
    DealContactLinkEntity,
  );

  const deals = await dealRepository
    .createQueryBuilder('deal')
    .select('deal.id', 'id')
    .where('deal."companyId" IN (:...companyIds)', { companyIds })
    .getRawMany<{ id: string }>();

  const dealIds = deals.map((deal) => deal.id);

  if (dealIds.length > 0) {
    await dealContactLinkRepository
      .createQueryBuilder()
      .delete()
      .where('"dealId" IN (:...dealIds)', { dealIds })
      .execute();

    await dealRepository
      .createQueryBuilder()
      .delete()
      .where('id IN (:...dealIds)', { dealIds })
      .execute();
  }

  const contactCompanyLinkRepository = dataSource.getRepository(
    ContactCompanyLinkEntity,
  );
  const contactRepository = dataSource.getRepository(ContactEntity);

  const linkedContacts = await contactCompanyLinkRepository
    .createQueryBuilder('link')
    .select('DISTINCT link."contactId"', 'contactId')
    .where('link."companyId" IN (:...companyIds)', { companyIds })
    .getRawMany<{ contactId: string }>();

  await contactCompanyLinkRepository
    .createQueryBuilder()
    .delete()
    .where('"companyId" IN (:...companyIds)', { companyIds })
    .execute();

  const contactIds = linkedContacts.map((contact) => contact.contactId);

  if (contactIds.length > 0) {
    const removableContacts = await contactRepository
      .createQueryBuilder('contact')
      .select('contact.id', 'id')
      .where('contact.id IN (:...contactIds)', { contactIds })
      .andWhere((queryBuilder) => {
        const remainingLinks = queryBuilder
          .subQuery()
          .select('1')
          .from(ContactCompanyLinkEntity, 'remainingLink')
          .where('remainingLink."contactId" = contact.id')
          .getQuery();

        return `NOT EXISTS ${remainingLinks}`;
      })
      .getRawMany<{ id: string }>();

    const removableContactIds = removableContacts.map((contact) => contact.id);

    if (removableContactIds.length > 0) {
      await contactRepository
        .createQueryBuilder('contact')
        .delete()
        .where('id IN (:...removableContactIds)', { removableContactIds })
        .execute();
    }
  }

  await companyRepository
    .createQueryBuilder()
    .delete()
    .where('id IN (:...companyIds)', { companyIds })
    .execute();
};

