type BuildDealInput = {
  companyId: string;
  name: string;
  value: number;
  stage?: string;
  contactLinks?: Array<{
    contactId: string;
    role?: string | null;
  }>;
  primaryContactId?: string | null;
  expectedCloseDate?: string | null;
};

export const buildDeal = ({
  companyId,
  name,
  value,
  stage,
  contactLinks,
  primaryContactId,
  expectedCloseDate,
}: BuildDealInput): {
  deal: Partial<DealEntity>;
  contactLinks: Array<{
    contactId: string;
    role: string | null;
  }>;
} => {
  const deal: Partial<DealEntity> = {
    companyId,
    name,
    value,
    stage: stage ?? 'lead',
    primaryContactId: primaryContactId ?? null,
  };

  if (expectedCloseDate !== undefined) {
    deal.expectedCloseDate = expectedCloseDate;
  }

  return {
    deal,
    contactLinks: (contactLinks ?? []).map((link) => ({
      contactId: link.contactId,
      role: link.role?.trim() ? link.role.trim() : null,
    })),
  };
};

