  name: '',
  value: '',
  stage: 'lead',
  companyId: '',
  contactLinks: [],
  primaryContactId: null,
  expectedCloseDate: '',
};

function parseDateValue(value) {
  if (!value) {
    return '';
  }

  return value.slice(0, 10);
}

export function DealFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    name: false,
    value: false,
    companyId: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList({
    page: 1,
    pageSize: 100,
    companyId: values.companyId || undefined,
  });

  const companyOptions = useMemo(
    () => companiesQuery.data?.items ?? [],
    [companiesQuery.data?.items],
  );
  const selectedCompany = useMemo(
    () =>
      companyOptions.find((company) => company.id === values.companyId) ??
      (values.companyId
        ? {
            id: values.companyId,
            name: initialValues?.company?.name || values.companyId,
          }
        : null),
    [companyOptions, initialValues?.company?.name, values.companyId],
  );

  const contactOptions = useMemo(
    () => (values.companyId ? contactsQuery.data?.items ?? [] : []),
    [contactsQuery.data?.items, values.companyId],
  );

  const selectedContacts = useMemo(
    () =>
      values.contactLinks
        .map(
          (link) =>
            contactOptions.find((contact) => contact.id === link.contactId) ?? {
              id: link.contactId,
              name: link.contactId,
            },
        )
        .filter(Boolean),
    [contactOptions, values.contactLinks],
  );

  const numericValue = Number(values.value);

  const errors = {
    name: !values.name?.trim() ? 'Name is required.' : '',
    value:
      values.value === '' || Number.isNaN(numericValue)
        ? 'Value is required.'
        : numericValue < 0
          ? 'Value must be non-negative.'
          : '',
    companyId: !values.companyId ? 'Company is required.' : '',
    primaryContactId:
      values.primaryContactId &&
      !values.contactLinks.some((link) => link.contactId === values.primaryContactId)
        ? 'Primary contact must exist in linked contacts.'
        : '',
  };

  const isFormValid =
    !errors.name && !errors.value && !errors.companyId && !errors.primaryContactId;

  useEffect(() => {
    if (!open) {
      return;
    }

    const contactLinks = normalizeDealContactLinks(initialValues);

    setValues({
      ...emptyValues,
      ...initialValues,
      value:
        initialValues?.value === undefined || initialValues?.value === null
          ? ''
          : String(initialValues.value),
      stage: initialValues?.stage || 'lead',
      contactLinks,
      primaryContactId:
        initialValues?.primaryContactId ??
        (contactLinks.length === 1 ? contactLinks[0].contactId : null),
      expectedCloseDate: parseDateValue(initialValues?.expectedCloseDate),
    });
    setTouched({ name: false, value: false, companyId: false });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    setValues((current) => ({
      ...current,
      companyId: company?.id || '',
      contactLinks: [],
      primaryContactId: null,
    }));
  };

  const handleContactSelectionChange = (_, contacts) => {
    const selectedIds = contacts.map((contact) => contact.id);

    setValues((current) => {
      const nextLinks = selectedIds.map((contactId) => {
        const existingLink = current.contactLinks.find(
          (link) => link.contactId === contactId,
        );

        return {
          contactId,
          role: existingLink?.role ?? '',
        };
      });

      return {
        ...current,
        contactLinks: nextLinks,
        primaryContactId:
          nextLinks.length === 1
            ? nextLinks[0].contactId
            : nextLinks.some((link) => link.contactId === current.primaryContactId)
              ? current.primaryContactId
              : null,
      };
    });
  };

  const handlePrimaryChange = (event) => {
    setValues((current) => ({
      ...current,
      primaryContactId: event.target.value || null,
    }));
  };

  const handleRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((link) =>
        link.contactId === contactId ? { ...link, role } : link,
      ),
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ name: true, value: true, companyId: true });

    if (!isFormValid) {
      return;
    }

    const payload = {
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage?.trim() || undefined,
      contactLinks: values.contactLinks.map((link) => ({
        contactId: link.contactId,
        role: link.role?.trim() || null,
      })),
      primaryContactId: values.primaryContactId || null,
      expectedCloseDate: values.expectedCloseDate || null,
    };

    if (mode === 'create') {
      await onSubmit({
        ...payload,
        companyId: values.companyId,
      });
      return;
    }

    await onSubmit(payload);
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            autoFocus
            required
            label="Name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              type="number"
              label="Value"
              value={values.value}
              onBlur={handleBlur('value')}
              onChange={handleChange('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
              inputProps={{ min: 0, step: '0.01' }}
            />
            <TextField
              fullWidth
              label="Stage"
              value={values.stage}
              onChange={handleChange('stage')}
              placeholder="lead"
            />
          </Stack>

          <Autocomplete
            fullWidth
            options={companyOptions}
            value={selectedCompany}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyId')}
            onChange={handleCompanyChange}
            disabled={mode === 'edit'}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
              />
            )}
          />

          <DealContactLinksEditor
            contactOptions={contactOptions}
            contactLinks={values.contactLinks}
            contactsQuery={contactsQuery}
            errors={errors}
            onContactSelectionChange={handleContactSelectionChange}
            onPrimaryChange={handlePrimaryChange}
            onRoleChange={handleRoleChange}
            primaryContactId={values.primaryContactId}
            selectedContacts={selectedContacts}
            values={values}
          />

          <TextField
            label="Expected Close Date"
            type="date"
            InputLabelProps={{ shrink: true }}
            value={values.expectedCloseDate}
            onChange={handleChange('expectedCloseDate')}
          />

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}
import Box from '@mui/material/Box';
import Chip from '@mui/material/Chip';
import CircularProgress from '@mui/material/CircularProgress';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import ArrowLeftOutlined from '@ant-design/icons/ArrowLeftOutlined';
import { Link, useParams } from 'react-router-dom';

import MainCard from 'components/MainCard';
import IconButton from 'components/IconButton';
import { isTransportError } from 'api/request';
import formatDate from 'utils/formatDate';
import { useDeal } from './dealQueries';

function formatCurrency(value) {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 2,
  }).format(value ?? 0);
}

function DetailRow({ label, value }) {
  return (
    <Stack direction="row" spacing={2} sx={{ justifyContent: 'space-between' }}>
      <Typography color="text.secondary">{label}</Typography>
      <Typography>{value || '—'}</Typography>
    </Stack>
  );
}

function ContactLinksRow({ deal }) {
  const links = deal.contactLinks ?? [];

  if (links.length === 0) {
    return <DetailRow label="Contacts" value="—" />;
  }

  return (
    <Stack spacing={1}>
      <Typography color="text.secondary">Contacts</Typography>
      <Stack spacing={1}>
        {links.map((link) => (
          <Stack
            key={link.contactId}
            direction={{ xs: 'column', sm: 'row' }}
            spacing={1}
            alignItems={{ xs: 'flex-start', sm: 'center' }}
          >
            <Typography>{link.contactId}</Typography>
            {link.role ? <Chip label={link.role} size="small" variant="outlined" /> : null}
            {deal.primaryContactId === link.contactId ? (
              <Chip label="Primary" size="small" color="primary" />
            ) : null}
          </Stack>
        ))}
      </Stack>
    </Stack>
  );
}

export default function DealDetail() {
  const { id } = useParams();
  const dealQuery = useDeal(id);
  const deal = dealQuery.data;

  return (
    <Stack spacing={2}>
      <IconButton component={Link} to="/deals" aria-label="Back to deals" shape="rounded">
        <ArrowLeftOutlined />
      </IconButton>

      <MainCard title={deal?.name || 'Deal detail'}>
        {dealQuery.isLoading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
            <CircularProgress />
          </Box>
        ) : null}

        {dealQuery.isError && !isTransportError(dealQuery.error) ? (
          <Typography color="error">{dealQuery.error?.message || 'Failed to load deal.'}</Typography>
        ) : null}

        {deal ? (
          <Stack spacing={1.5}>
            <DetailRow label="ID" value={deal.id} />
            <DetailRow label="Company" value={deal.company?.name || deal.companyId} />
            <DetailRow label="Stage" value={deal.stage} />
            <DetailRow label="Value" value={formatCurrency(deal.value)} />
            <ContactLinksRow deal={deal} />
            <DetailRow label="Expected Close Date" value={deal.expectedCloseDate} />
            <DetailRow label="Created" value={formatDate(deal.createdAt)} />
            <DetailRow label="Updated" value={formatDate(deal.updatedAt)} />
          </Stack>
        ) : null}
      </MainCard>
    </Stack>
  );
}
