import { Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import { DealContactLinkEntity } from './deal-contact-link.entity';

export type DealContactLinkView = {
  contactId: string;
  role: string | null;
};

@Injectable()
export class DealContactLinkRepository extends BaseRepository<DealContactLinkEntity> {
  constructor(dataSource: DataSource) {
    super(DealContactLinkEntity, dataSource.createEntityManager());
  }

  async findByDealIds(dealIds: string[]) {
    if (dealIds.length === 0) {
      return new Map<string, DealContactLinkView[]>();
    }

    const links = await this.find({
      where: dealIds.map((dealId) => ({ dealId })),
      order: {
        dealId: 'ASC',
        createdAt: 'ASC',
      },
    });

    const map = new Map<string, DealContactLinkView[]>();

    for (const link of links) {
      const current = map.get(link.dealId) ?? [];
      current.push({
        contactId: link.contactId,
        role: link.role,
      });
      map.set(link.dealId, current);
    }

    return map;
  }

  async findByDealId(dealId: string) {
    const links = await this.find({
      where: { dealId },
      order: {
        createdAt: 'ASC',
      },
    });

    return links.map((link) => ({
      contactId: link.contactId,
      role: link.role,
    }));
  }
}
