import { HttpStatus, Injectable } from '@nestjs/common';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import { ContactCompanyLinkEntity } from './contact-company-link.entity';
import {
  ContactCompanyLinkRepository,
  ContactCompanySummary,
} from './contact-company-link.repository';
import { ContactEntity } from './contact.entity';
import { ContactRepository } from './contact.repository';
import {
  ContactCompanyLinkInputDto,
  ContactListQueryDto,
  CreateContactDto,
  UpdateContactDto,
  UpdateContactCompanyLinkInputDto,
} from './dto';

@Injectable()
export class ContactService {
  constructor(
    private readonly contactRepository: ContactRepository,
    private readonly contactCompanyLinkRepository: ContactCompanyLinkRepository,
    private readonly companyService: CompanyService,
  ) {}

  async createContact(dto: CreateContactDto): Promise<ContactEntity> {
    this.validateCompanyLinks(
      dto.companies,
      'companies',
      'Contact must include one or more companies with exactly one primary company.',
    );

    await this.ensureCompaniesExist(dto.companies.map((company) => company.id));

    const { companies, ...contactPayload } = dto;

    const createdContact = await this.contactRepository.manager.transaction(
      async (manager) => {
        const contact = await manager
          .getRepository(ContactEntity)
          .save(manager.getRepository(ContactEntity).create(contactPayload));

        await manager.getRepository(ContactCompanyLinkEntity).save(
          companies.map((company) =>
            manager.getRepository(ContactCompanyLinkEntity).create({
              contactId: contact.id,
              companyId: company.id,
              isPrimary: company.isPrimary,
            }),
          ),
        );

        return contact;
      },
    );

    return this.getContactById(createdContact.id);
  }

  async getContactsList(query: ContactListQueryDto) {
    const [items, total] = await this.contactRepository.findWithFilter(query);
    const hydratedItems = await this.hydrateContacts(items);

    const pageSize = query.pageSize ?? 20;
    const page = query.page ?? 1;

    return {
      items: hydratedItems,
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
    };
  }

  async getContactById(id: string): Promise<ContactEntity> {
    const contact = await this.getExistingContactEntity(id);
    const hydratedContacts = await this.hydrateContacts([contact]);

    return hydratedContacts[0];
  }

  async updateContact(
    id: string,
    dto: UpdateContactDto,
  ): Promise<ContactEntity> {
    const contact = await this.getExistingContactEntity(id);

    if (dto.companies) {
      this.validateCompanyLinks(
        dto.companies,
        'companies',
        'Contact must include one or more companies with exactly one primary company.',
      );

      await this.ensureCompaniesExist(
        dto.companies.map((company) => company.id),
      );

      const existingLinks =
        await this.contactCompanyLinkRepository.findLinksByContactId(id);
      this.ensurePrimaryLinkStateForReplacement(existingLinks, dto.companies);

      const { companies, ...contactPayload } = dto;

      await this.contactRepository.manager.transaction(async (manager) => {
        const mergedContact = manager
          .getRepository(ContactEntity)
          .merge(contact, contactPayload);

        await manager.getRepository(ContactEntity).save(mergedContact);

        await manager
          .getRepository(ContactCompanyLinkEntity)
          .delete({ contactId: id });

        await manager.getRepository(ContactCompanyLinkEntity).save(
          companies.map((company) =>
            manager.getRepository(ContactCompanyLinkEntity).create({
              contactId: id,
              companyId: company.id,
              isPrimary: company.isPrimary,
            }),
          ),
        );
      });

      return this.getContactById(id);
    }

    const updatedContact = this.contactRepository.merge(contact, dto);
    await this.contactRepository.save(updatedContact);

    return this.getContactById(id);
  }

  async removeContact(id: string): Promise<void> {
    await this.getExistingContactEntity(id);
    await this.contactRepository.softDelete(id);
  }

  private async hydrateContacts(contacts: ContactEntity[]) {
    if (contacts.length === 0) {
      return [];
    }

    const companyMap =
      await this.contactCompanyLinkRepository.findCompanySummariesByContactIds(
        contacts.map((contact) => contact.id),
      );

    return contacts.map((contact) => ({
      ...contact,
      companies: this.sortCompanies(companyMap.get(contact.id) ?? []),
    }));
  }

  private sortCompanies(companies: ContactCompanySummary[]) {
    return [...companies].sort((left, right) => {
      if (left.isPrimary === right.isPrimary) {
        return left.name.localeCompare(right.name);
      }

      return left.isPrimary ? -1 : 1;
    });
  }

  private async ensureCompaniesExist(companyIds: string[]) {
    for (const companyId of companyIds) {
      try {
        await this.companyService.getCompanyById(companyId);
      } catch (error) {
        if (this.isNotFoundException(error)) {
          throw new AppException({
            statusCode: HttpStatus.NOT_FOUND,
            code: BUSINESS_ERROR_CODES.NOT_FOUND,
            message: `Company with ID ${companyId} not found`,
            details: {
              resource: 'Company',
              id: companyId,
            },
          });
        }

        throw error;
      }
    }
  }

  private validateCompanyLinks(
    companies:
      ContactCompanyLinkInputDto[] | UpdateContactCompanyLinkInputDto[],
    field: string,
    message: string,
  ) {
    if (companies.length === 0) {
      throw this.createValidationException(field, message);
    }

    const primaryCount = companies.filter(
      (company) => company.isPrimary,
    ).length;

    if (primaryCount !== 1) {
      throw this.createValidationException(field, message);
    }

    const uniqueCompanyIds = new Set(companies.map((company) => company.id));

    if (uniqueCompanyIds.size !== companies.length) {
      throw this.createValidationException(
        field,
        'Duplicate company links are not allowed.',
      );
    }
  }

  private ensurePrimaryLinkStateForReplacement(
    existingLinks: ContactCompanyLinkEntity[],
    nextLinks: UpdateContactCompanyLinkInputDto[],
  ) {
    const existingPrimary = existingLinks.find((link) => link.isPrimary);

    if (!existingPrimary) {
      return;
    }

    const nextPrimary = nextLinks.find((link) => link.isPrimary);

    if (!nextPrimary) {
      return;
    }

    if (nextPrimary.id === existingPrimary.companyId) {
      return;
    }

    const nextLinkCompanyIds = new Set(nextLinks.map((link) => link.id));

    if (nextLinkCompanyIds.has(existingPrimary.companyId)) {
      return;
    }

    const existingCompanyIds = new Set(
      existingLinks.map((link) => link.companyId),
    );

    if (!existingCompanyIds.has(nextPrimary.id)) {
      throw new AppException({
        statusCode: HttpStatus.CONFLICT,
        code: BUSINESS_ERROR_CODES.INVALID_LINK_STATE,
        message:
          'Primary company cannot be detached unless another existing linked company becomes primary in the same operation.',
        details: {
          contactId: existingPrimary.contactId,
          primaryCompanyId: existingPrimary.companyId,
          nextPrimaryCompanyId: nextPrimary.id,
        },
      });
    }
  }

  private async getExistingContactEntity(id: string) {
    const contact = await this.contactRepository.findOne({ where: { id } });

    if (!contact) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.NOT_FOUND,
        message: `Contact with ID ${id} not found`,
        details: {
          resource: 'Contact',
          id,
        },
      });
    }

    return contact;
  }

  private createValidationException(field: string, message: string) {
    return new AppException({
      statusCode: HttpStatus.BAD_REQUEST,
      code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
      message,
      details: {
        errors: [
          {
            field,
            messages: [message],
          },
        ],
      },
    });
  }

  private isNotFoundException(error: unknown): boolean {
    return (
      error instanceof AppException &&
      error.getStatus() === HttpStatus.NOT_FOUND
    );
  }
}

