import { faker } from '@faker-js/faker';
import {
  CompanyEntity,
  CompanyStatus,
  Industry,
} from '../../../modules/company/company.entity';
import { ContactCompanyLinkEntity } from '../../../modules/contact/contact-company-link.entity';
import { ContactEntity } from '../../../modules/contact/contact.entity';
import { DealContactLinkEntity } from '../../../modules/deal/deal-contact-link.entity';
import { DealEntity } from '../../../modules/deal/deal.entity';
import { buildCompany } from '../factories/company.factory';
import { buildContact } from '../factories/contact.factory';
import { buildDeal } from '../factories/deal.factory';
import { SeedContext, SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const DEMO_PREFIX = 'Demo Seed Company';
const STATUSES = [
  CompanyStatus.ACTIVE,
  CompanyStatus.INACTIVE,
  CompanyStatus.PENDING,
] as const;
const INDUSTRIES = [
  Industry.TECHNOLOGY,
  Industry.FINANCE,
  Industry.MANUFACTURING,
  Industry.RETAIL,
  Industry.OTHER,
] as const;
const DEAL_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
] as const;

type DemoCompanyRecord = {
  company: CompanyEntity;
  contactIds: string[];
};

const saveContactWithLinks = async (
  context: SeedContext,
  input: ReturnType<typeof buildContact>,
) => {
  const contactRepository = context.dataSource.getRepository(ContactEntity);
  const linkRepository = context.dataSource.getRepository(
    ContactCompanyLinkEntity,
  );

  const savedContact = await contactRepository.save(
    contactRepository.create(input.contact),
  );

  await linkRepository.save(
    input.companyLinks.map((companyLink) =>
      linkRepository.create({
        contactId: savedContact.id,
        companyId: companyLink.companyId,
        isPrimary: companyLink.isPrimary,
      }),
    ),
  );

  return savedContact;
};

const saveDealWithLinks = async (
  context: SeedContext,
  input: ReturnType<typeof buildDeal>,
) => {
  const dealRepository = context.dataSource.getRepository(DealEntity);
  const linkRepository = context.dataSource.getRepository(
    DealContactLinkEntity,
  );

  const savedDeal = await dealRepository.save(
    dealRepository.create(input.deal),
  );

  if (input.contactLinks.length > 0) {
    await linkRepository.save(
      input.contactLinks.map((contactLink) =>
        linkRepository.create({
          dealId: savedDeal.id,
          contactId: contactLink.contactId,
          role: contactLink.role,
        }),
      ),
    );
  }

  return savedDeal;
};

const createDemoCompanies = async (context: SeedContext) => {
  const companyRepository = context.dataSource.getRepository(CompanyEntity);
  let contactsCreated = 0;
  const companyRecords: DemoCompanyRecord[] = [];

  await cleanupCompaniesByPrefixes(context, [DEMO_PREFIX]);

  for (let companyIndex = 0; companyIndex < 10; companyIndex += 1) {
    const companyName = `${DEMO_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`;
    const company = await companyRepository.save(
      companyRepository.create(
        buildCompany({
          name: companyName,
          status: STATUSES[companyIndex % STATUSES.length],
          industry: INDUSTRIES[companyIndex % INDUSTRIES.length],
          lastContactedAt: distributeRecentDate(context.now, companyIndex, 10),
          email: `demo-company-${companyIndex + 1}@baseline.local`,
        }),
      ),
    );

    const contactsForCompany = 2 + (companyIndex % 4);
    const contactIds: string[] = [];

    for (
      let contactIndex = 0;
      contactIndex < contactsForCompany;
      contactIndex += 1
    ) {
      contactsCreated += 1;

      const contact = await saveContactWithLinks(
        context,
        buildContact({
          companies: [{ companyId: company.id, isPrimary: true }],
          name: faker.person.fullName(),
          lastContactedAt: distributeRecentDate(
            context.now,
            companyIndex + contactIndex,
            14,
          ),
          email: `demo-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
          role: [
            'Decision Maker',
            'User',
            'Finance Reviewer',
            'Technical Buyer',
          ][contactIndex % 4],
        }),
      );

      contactIds.push(contact.id);
    }

    companyRecords.push({ company, contactIds });
  }

  if (companyRecords.length >= 2 && companyRecords[0].contactIds.length > 0) {
    const linkRepository = context.dataSource.getRepository(
      ContactCompanyLinkEntity,
    );

    await linkRepository.save(
      linkRepository.create({
        contactId: companyRecords[0].contactIds[0],
        companyId: companyRecords[1].company.id,
        isPrimary: false,
      }),
    );
  }

  return {
    contactsCreated,
    companyRecords,
  };
};

const createDemoDeals = async (
  context: SeedContext,
  companyRecords: DemoCompanyRecord[],
) => {
  let dealsCreated = 0;

  for (const [companyIndex, record] of companyRecords.entries()) {
    const stage = DEAL_STAGES[companyIndex % DEAL_STAGES.length];
    const expectedCloseDate =
      companyIndex % 3 === 0
        ? null
        : new Date(
            Date.UTC(2026, (companyIndex % 11) + 1, 5 + (companyIndex % 20)),
          )
            .toISOString()
            .slice(0, 10);

    const defaultContactLinks =
      companyIndex % 4 === 0 || record.contactIds.length === 0
        ? []
        : [{ contactId: record.contactIds[0], role: null }];

    const isMultiContactDeal =
      companyIndex === 2 && record.contactIds.length >= 3;
    const contactLinks = isMultiContactDeal
      ? [
          { contactId: record.contactIds[0], role: 'decision-maker' },
          { contactId: record.contactIds[1], role: 'legal' },
          { contactId: record.contactIds[2], role: 'it-lead' },
        ]
      : defaultContactLinks;

    const primaryContactId =
      contactLinks.length > 0 ? contactLinks[0].contactId : null;

    await saveDealWithLinks(
      context,
      buildDeal({
        name: `Demo Deal ${String(companyIndex + 1).padStart(2, '0')} for ${record.company.name}`,
        value: 10000 + companyIndex * 2500,
        stage,
        companyId: record.company.id,
        contactLinks,
        primaryContactId,
        expectedCloseDate,
      }),
    );

    dealsCreated += 1;
  }

  return dealsCreated;
};

export const demoSeedScenario: SeedScenario = {
  name: 'demo',
