import { Alert, Box, CircularProgress, Stack } from '@mui/material';

import { EmptyState } from '../EmptyState/EmptyState';
import { DataTableToolbar } from '../Toolbar/Toolbar';

export function DataTableShell({
  actions,
  children,
  description,
  emptyDescription,
  emptyTitle,
  error,
  filters,
  isEmpty,
  loading,
  pagination,
  onReset,
  onSearchChange,
  onSearchSubmit,
  searchPlaceholder,
  searchValue,
  title,
}) {
  return (
    <Stack component="section" spacing={2.5}>
      <DataTableToolbar
        actions={actions}
        description={description}
        filters={filters}
        onReset={onReset}
        onSearchChange={onSearchChange}
        onSearchSubmit={onSearchSubmit}
        searchPlaceholder={searchPlaceholder}
        searchValue={searchValue}
        title={title}
      />

      <Stack spacing={2}>
        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', py: 6 }}>
            <CircularProgress />
          </Box>
        ) : null}

        {!loading && error ? <Alert severity="error">{error}</Alert> : null}

        {!loading && !error && isEmpty ? (
          <EmptyState title={emptyTitle} description={emptyDescription} />
        ) : null}

        {!loading && !error && !isEmpty ? children : null}

        {!loading && !error && pagination ? pagination : null}
      </Stack>
    </Stack>
  );
}

export { DataTableShell as TableShell };

import { Button, Stack, TextField, Typography } from '@mui/material';

import styles from './Toolbar.module.scss';

export function DataTableToolbar({
  actions,
  description,
  filters,
  onReset,
  onSearchChange,
  onSearchSubmit,
  searchPlaceholder,
  searchValue,
  title,
}) {
  return (
    <div className={styles.toolbarShell}>
      <div className={styles.headerRow}>
        <div>
          <Typography variant="h4">{title}</Typography>
          {description ? (
            <Typography className={styles.description}>{description}</Typography>
          ) : null}
        </div>
        {actions ? <div className={styles.actions}>{actions}</div> : null}
      </div>

      <form className={styles.filtersForm} onSubmit={onSearchSubmit}>
        <TextField
          size="small"
          placeholder={searchPlaceholder}
          value={searchValue}
          onChange={(event) => onSearchChange(event.target.value)}
          className={styles.searchField}
        />

        {filters ? <div className={styles.filters}>{filters}</div> : null}

        <Stack direction="row" spacing={1} className={styles.submitActions}>
          <Button type="submit" variant="contained">
            Query
          </Button>
          <Button type="button" onClick={onReset}>
            Reset
          </Button>
        </Stack>
      </form>
    </div>
  );
}

export { DataTableToolbar as Toolbar };

const handleResetFilters = () => {
  setStageInput('');
  setCompanyInput('');
  setListQuery((current) => ({ page: 1, pageSize: current.pageSize }));
};

const handleFormSubmit = async (payload) => {
  setFormErrors({ stage: '' });

  try {
    if (formState.mode === 'create') {
      await createDeal.mutateAsync(payload);
      setFeedback({
        open: true,
        severity: 'success',
        message: 'Deal created.',
      });
    } else {
      await updateDeal.mutateAsync({
        id: formState.deal.id,
        data: payload,
      });
      setFeedback({
        open: true,
        severity: 'success',
        message: 'Deal updated.',
      });
    }

    setFormErrors({ stage: '' });
    setFormState({ open: false, mode: 'create', deal: null });
  } catch (error) {
    if (!isTransportError(error)) {
      if (STAGE_ERROR_CODES.has(error?.code)) {
        setFormErrors({
          stage: extractErrorMessage(error, 'Invalid stage transition.'),
        });
        return;
      }

      setFeedback({
        open: true,
        severity: 'error',
        message: extractErrorMessage(error, 'Deal request failed.'),
      });
    }
  }
};

const dealPage = dealsQuery.data;
const dealItems = dealPage?.items ?? [];

return (
  <Stack spacing={3}>
    <DataTableShell
      title="Deals"
      searchValue={stageInput}
      onSearchChange={setStageInput}
      onSearchSubmit={handleSearchSubmit}
      onReset={handleResetFilters}
      searchPlaceholder="Filter by stage (exact match)"
      filters={(
        <TextField
          select
          size="small"
          label="Company"
          value={companyInput}
          onChange={(event) => setCompanyInput(event.target.value)}
          sx={{ minWidth: '14rem' }}
        >
          <MenuItem value="">All companies</MenuItem>
          {companyOptions.map((company) => (
            <MenuItem key={company.id} value={company.id}>
              {company.name}
            </MenuItem>
          ))}
        </TextField>
      )}
      actions={(
        <Button
          variant="contained"
          startIcon={<PlusOutlined />}
          onClick={() =>
            {
              setFormErrors({ stage: '' });
              setFormState({
                open: true,
                mode: 'create',
                deal: null,
              });
            }
          }
        >
          Add Deal
        </Button>
      )}
      loading={dealsQuery.isLoading}
      error={
        dealsQuery.isError && !isTransportError(dealsQuery.error)
          ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
          : null
      }
      isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && dealItems.length === 0}
      emptyTitle="No matching deals"
      emptyDescription="Try adjusting stage/company filters or clear filters."
      pagination={
        dealPage && dealPage.total > 0 ? (
          <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
            <DataTablePagination
              page={dealPage.page}
              pageSize={dealPage.pageSize}
              total={dealPage.total}
              totalPages={dealPage.totalPages}
              onPageChange={(page) =>
                setListQuery((current) => ({
                  ...current,
                  page,
                }))
              }
              onPageSizeChange={(pageSize) =>
                setListQuery((current) => ({
                  ...current,
                  page: 1,
                  pageSize,
                }))
              }
            />
          </Box>
        ) : null
      }
    >
      <DealTable
        deals={dealItems}
        companyNameById={companyNameById}
        onView={(deal) => navigate(`/deals/${deal.id}`)}
        onEdit={(deal) =>
          {
            setFormErrors({ stage: '' });
            setFormState({
              open: true,
              mode: 'edit',

                mode: 'edit',
                deal,
              });
            }
          }
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => {
          setFormErrors({ stage: '' });
          setFormState({ open: false, mode: 'create', deal: null });
        }}
        onSubmit={handleFormSubmit}
        stageErrorMessage={formErrors.stage}
        onStageErrorClear={() => setFormErrors({ stage: '' })}
      />

      <Snackbar
        open={feedback.open}
        autoHideDuration={3200}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
      >
        <Alert
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
          severity={feedback.severity}
          variant="filled"
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
}

