import { describe, expect, it } from 'vitest';
import {
  CREATE_STAGE_OPTIONS,
  getStageLabel,
  getTransitionOptions,
} from './dealStageModel';

describe('dealStageModel', () => {
  it('limits create options to lead and qualified', () => {
    expect(CREATE_STAGE_OPTIONS).toEqual(['lead', 'qualified']);
  });

  it('omits active transition when no contacts are linked', () => {
    expect(
      getTransitionOptions({
        currentStage: 'qualified',
        hasLinkedContacts: false,
      }),
    ).toEqual(['closed_lost']);
  });

  it('returns only lead as a transition from closed_lost', () => {
    expect(
      getTransitionOptions({
        currentStage: 'closed_lost',
        hasLinkedContacts: true,
      }),
    ).toEqual(['lead']);
  });

  it('returns no transitions from closed_won', () => {
    expect(
      getTransitionOptions({
        currentStage: 'closed_won',
        hasLinkedContacts: true,
      }),
    ).toEqual([]);
  });

  it('formats canonical stage labels for display', () => {
    expect(getStageLabel('lead')).toBe('Lead');
    expect(getStageLabel('closed_won')).toBe('Closed Won');
  });
});
EOF"

