import { act, renderHook, waitFor } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { useDealFormState } from './useDealFormState';

vi.mock('../companies/companyQueries', () => ({
  useCompanyList: () => ({
    data: { items: [] },
    isLoading: false,
    isError: false,
  }),
}));

vi.mock('../contacts/contactQueries', () => ({
  useContactList: () => ({
    data: { items: [] },
    isLoading: false,
    isError: false,
  }),
}));

describe('useDealFormState', () => {
  const baseInitialValues = {
    name: 'Deal A',
    value: 100,
    companyId: 'company-1',
    stage: 'active',
    contactLinks: [{ contactId: 'contact-1', role: 'owner' }],
    primaryContactId: 'contact-1',
    expectedCloseDate: null,
  };

  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('requires expected close date when transitioning to negotiation', async () => {
    const { result } = renderHook(() =>
      useDealFormState({
        initialValues: baseInitialValues,
        mode: 'edit',
        onStageErrorClear: vi.fn(),
        open: true,
        stageErrorMessage: '',
      }),
    );

    await waitFor(() => {
      expect(result.current.values.stage).toBe('active');
    });

    expect(result.current.transitionOptions).toEqual([
      'negotiation',
      'closed_lost',
    ]);

    act(() => {
      result.current.handleChange('stageTransitionTarget')({
        target: { value: 'negotiation' },
      });
    });

    expect(result.current.errors.expectedCloseDate).toBe(
      'Expected close date is required when moving to negotiation.',
    );

    act(() => {
      result.current.handleChange('expectedCloseDate')({
        target: { value: '2026-10-31' },
      });
    });

    expect(result.current.errors.expectedCloseDate).toBe('');
  });
});
